using namespace std;

struct date {
    int day;
    char *month;
    int year;
};

struct fio {
    char *name;
    char *surname;
    char *patronymic;
};

struct car {
    char *brand;
    fio owner;
    int engine_power;
    int mileage;
    date last_service;
};

void add_car(car *cars, int &n);
void print_cars(const car *cars, int n);
void search_cars(const car *cars, int n, date current_date);

int main() {
    int n;
    cout << "Enter the number of cars: ";
    cin >> n;
    cin.ignore();

    car *cars = new car[n];

    add_car(cars, n);
    print_cars(cars, n);

    time_t now = time(0);
    tm *ltm = localtime(&now);
    date current_date;
    current_date.day = ltm->tm_mday;
    current_date.month = new char[20];
    strcpy(current_date.month, “xx”);
    current_date.year = 1900 + ltm->tm_year;

    search_cars(cars, n, current_date);

