void find_brand(const car *cars, int n, const char *brand);
void sort_print_high_mileage(car *cars, int n, int mileage_limit);
void save_data(const car *cars, int n, const string &file_name);
void free_memory(car *cars, int n);

int main() {
    int n;
    cout << "Enter the number of cars: ";
    cin >> n;
    cin.ignore();

    car *cars = new car[n];

    load_data(cars, n, “cars_data.txt”);

    bool exit = false;
    while (!exit) {
        int choice;
        cout << “1. Add a new car” << endl;
        cout << “2. Print car information” << endl;
        cout << “3. Find cars with more than 18 months since last service” << endl;
        cout << “4. Find cars of a specified brand” << endl;
        cout << “5. Find owners with mileage greater than specified (sorted by alphabet)” << endl;
        cout << “6. Exit” << endl;
        cout << "Choose an action: ";
        cin >> choice;
        cin.ignore();

        time_t now = time(0);
        tm *ltm = localtime(&now);
        date current_date;
        current_date.day = ltm->tm_mday;
        current_date.month = new char[20];
        strcpy(current_date.month, “xx”);
        current_date.year = 1900 + ltm->tm_year;

