}

void load_data(car *cars, int n, const string &file_name) {
    ifstream input_file(file_name);
    if (!input_file.is_open()) {
        cerr << “Failed to open file for reading.” << endl;
        return;
    }

    for (int i = 0; i < n; i++) {
        cars[i].brand = new char[20];
