def random_car(request):
    data = []

    for _ in range(1000):
        marque = random.choice(CAR_BRANDS)
        modele = fake.word()

        voiture = {
            'marque': marque,
            'modele': modele,
            'annee': random.randint(2000, 2023),
            'prix_journee': random.uniform(50, 200),
            'image_url': fetch_car_images()
            # 'image_url' : ''
        }
        data.append(voiture)

    return JsonResponse(data, safe=False)





def fetch_car_images():
    ACCESS_KEY = "cYQfREgK4t42xtlRO4su9064vJbTsB_vLjjHsxph5aA"
    IMAGE_COUNT=1000
    url = 'https://api.unsplash.com/photos/random'

    headers = {
        'Accept-Version': 'v1',
        'Authorization': f'Client-ID {ACCESS_KEY}'
    }

    params = {
        'query': 'car',
        'count': IMAGE_COUNT
    }

    response = requests.get(url, headers=headers, params=params)
