I've got this function getFutureDates that helps me render days based on the current day so that the next 2 weeks in business days are always shown, but when it's a Saturday is renders only the next 4 days. How can I fix it?

export const addBusinessDayRange = (date: Date) =>
  addBusinessDays(date, 10 - getDay(date));

export const getFutureDates = () => {
  const now = new Date('2023-05-27');
  const twoMondaysFromNow = startOfDay(addDays(nextMonday(now), 7));
  const fourMondaysFromNow = startOfDay(addDays(twoMondaysFromNow, 14));
  const twoFridaysFromTwoMondays = endOfDay(
    addBusinessDayRange(twoMondaysFromNow)
  );
  const twoFridaysFromFourMondays = endOfDay(
    addBusinessDayRange(fourMondaysFromNow)
  );
  const today = startOfDay(now);
  const twoFridaysFromToday = endOfDay(addBusinessDayRange(today));

  return {
    twoMondaysFromNow,
    fourMondaysFromNow,
    twoFridaysFromFourMondays,
    twoFridaysFromTwoMondays,
    today,
    twoFridaysFromToday
  };
};

