%% Step 1: Load and preprocess the data
% Load the historical temperature data for July
% Assuming the data is in a CSV file with two columns: year and temperature
load Month_data\Data_Temp.mat

ts = timeseries(Data,TimeLabel);
ts.Name = 'Close';
ts.TimeInfo.Format = 'mmm dd, yyyy';
figure
plot(ts,'LineWidth',2)
title('Mashhad dry bulb')

%% Step 2: Fit a time series model
% Fit an ARIMA model to the temperature data
model = arima('ARLags', 1:12, 'Seasonality', 12);
fit = estimate(model, ts);

% Alternatively, fit an exponential smoothing model
% alpha = 0.2;
% beta = 0.2;
% gamma = 0.2;
% model = exponentialSmoothing('Additive', true, 'Trend', 'Linear', 'Seasonality', 12, 'Alpha', alpha, 'Beta', beta, 'Gamma', gamma);
% fit = fit(model, ts_monthly);

% Alternatively, fit a neural network model
% net = narnet(1:12, 10);
% [x,xi,ai,t] = preparets(net, [], ts_monthly.data');
% net = train(net,x,t,xi,ai);
% fit = net(ts_monthly.data');
% fit = cell2mat(fit)';
% fit = timeseries(fit,ts_monthly.time);

%% Step 3: Perform diagnostic checks
% Perform Ljung-Box test on the residuals
[h, pVal, QStat, crit] = lbqtest(fit.Residuals.Raw, 'Lags', 12);

% Plot the autocorrelation and partial autocorrelation functions of the residuals
figure;
subplot(2,1,1); autocorr(fit.Residuals.Raw);
subplot(2,1,2); parcorr(fit.Residuals.Raw);

%% Step 4: Forecast the temperature in 2060
% Create a date range for the forecast period
end_date = datetime(2060, 7, 1);
forecast_date_range = ts.time(end):calmonths(1):end_date;

% Forecast the temperature using the fitted model
forecast = forecast(fit, numel(ts.data), 'Y0', ts.data);

% Combine the historical data and the forecast
forecast = [ts; timeseries(forecast, forecast_date_range)];

%% Step 5: Perform sensitivity analysis
% Vary the parameters of the ARIMA model and refit the model to assess the impact on the forecast
model1 = arima('ARLags', 1:12, 'Seasonality', 12);
fit1 = estimate(model1, ts);

model2 = arima('ARLags', 1:14, 'Seasonality', 12);
fit2 = estimate(model2, ts);

model3 = arima('ARLags', 1:12, 'Seasonality', 6);
fit3 = estimate(model3, ts);

% Plot the forecasts under different scenarios
figure;
plot(ts, 'b')
hold on;
plot(forecast, 'r')
plot(forecast_date_range, forecast(fit1, numel(ts.data), 'Y0', ts.data), 'g')
plot(forecast_date_range, forecast(fit2, numel(ts.data), 'Y0', ts.data), 'm')
plot(forecast_date_range, forecast(fit3, numel(ts.data), 'Y0', ts.data), 'k')
title('Forecast Sensitivity Analysis')
legend('Actual', 'Base Forecast', 'Scenario 1', 'Scenario 2', 'Scenario 3')

