export class StripeWebhookController {
  constructor(private user: UsersService, private booking: BookingsService) {}
  @Post()
  async handleStripeWebhook(
    @Req() req: RawBodyRequest<Request>,
    @Res() res: Response,
  ): Promise<Booking> {
    const stripe = new Stripe(process.env.STRIPE_SECRET_KEY, {
      apiVersion: '2022-11-15',
    });

    const event = stripe.webhooks.constructEvent(
      req.rawBody,
      req.headers['stripe-signature'],
      process.env.STRIPE_WEBHOOK_SECRET,
    );

    try {
      if (event.type === 'checkout.session.completed') {
        const session = event.data.object as Stripe.Checkout.Session;
        const paymentIntentId = session.payment_intent;

        const { vanVariationId, extras, fromDate, toDate, vanId } = JSON.parse(
          session.metadata.bookingData,
        );

        const booking = await this.booking.create({
          fromDate,
          toDate,
          vanId,
          vanVariationId,
          extras,
          stripePaymentIntentId: paymentIntentId as string,
          user: {
            email: session.customer_details.email,
            name: session.customer_details.name,
            phone: session.customer_details.phone,
          },
          cost: session.amount_total / 100,
        });

        return booking;
      }
    } catch (error) {
      // Handle any errors that occur during webhook processing
      console.error('Error processing webhook:', error);
    }

    // Respond with a 200 status to acknowledge receipt of the webhook event
    res.status(200).send('Webhook Received');
  }
}

