var init_resources_loop;
function init_resources_loopLoopBegin(init_resources_loopLoopScheduler, snapshot) {
  return async function() {
    TrialHandler.fromSnapshot(snapshot); // update internal variables (.thisN etc) of the loop

    // set up handler to look after randomisation of conditions etc
    init_resources_loop = new TrialHandler({
      psychoJS: psychoJS,
      nReps: 1, method: TrialHandler.Method.SEQUENTIAL,
      extraInfo: expInfo, originPath: undefined,
      trialList: stim_file,
      seed: undefined, name: 'init_resources_loop'
    });
    psychoJS.experiment.addLoop(init_resources_loop); // add the loop to the experiment
    currentLoop = init_resources_loop;  // we're now the current loop

    // Schedule all the trials in the trialList:
    for (const thisInit_resources_loop of init_resources_loop) {
      snapshot = init_resources_loop.getSnapshot();
      init_resources_loopLoopScheduler.add(importConditions(snapshot));
      init_resources_loopLoopScheduler.add(init_resourcesRoutineBegin(snapshot));
      init_resources_loopLoopScheduler.add(init_resourcesRoutineEachFrame());
      init_resources_loopLoopScheduler.add(init_resourcesRoutineEnd(snapshot));
      init_resources_loopLoopScheduler.add(init_resources_loopLoopEndIteration(init_resources_loopLoopScheduler, snapshot));
    }

    return Scheduler.Event.NEXT;
  }
}


async function init_resources_loopLoopEnd() {
  // terminate loop
  psychoJS.experiment.removeLoop(init_resources_loop);
  // update the current loop from the ExperimentHandler
  if (psychoJS.experiment._unfinishedLoops.length>0)
    currentLoop = psychoJS.experiment._unfinishedLoops.at(-1);
  else
    currentLoop = psychoJS.experiment;  // so we use addData from the experiment
  return Scheduler.Event.NEXT;
}


function init_resources_loopLoopEndIteration(scheduler, snapshot) {
  // ------Prepare for next entry------
  return async function () {
    if (typeof snapshot !== 'undefined') {
      // ------Check if user ended loop early------
      if (snapshot.finished) {
        // Check for and save orphaned data
        if (psychoJS.experiment.isEntryEmpty()) {
          psychoJS.experiment.nextEntry(snapshot);
        }
        scheduler.stop();
      }
    return Scheduler.Event.NEXT;
    }
  };
}


