            continueRoutine = false;
        } else {
            // Else update the progress bar width
            for (let i = 0;  i < resources_total; i++) {
                if (psychoJS.serverManager.getResourceStatus(resource_names[i]).description == "DOWNLOADED") {
                    currently_uploaded += 1;
                    resources_pb_width = currently_uploaded / resources_total;
                }
            }
    }
    }



    // *resource_pb_bg* updates
    if (t >= 0.0 && resource_pb_bg.status === PsychoJS.Status.NOT_STARTED) {
      // keep track of start time/frame for later
      resource_pb_bg.tStart = t;  // (not accounting for frame time here)
      resource_pb_bg.frameNStart = frameN;  // exact frame index

      resource_pb_bg.setAutoDraw(true);
    }


    // *resource_pb_fg* updates
    if (t >= 0.0 && resource_pb_fg.status === PsychoJS.Status.NOT_STARTED) {
      // keep track of start time/frame for later
      resource_pb_fg.tStart = t;  // (not accounting for frame time here)
      resource_pb_fg.frameNStart = frameN;  // exact frame index

      resource_pb_fg.setAutoDraw(true);
    }


    if (resource_pb_fg.status === PsychoJS.Status.STARTED){ // only update if being drawn
      resource_pb_fg.setSize([(resources_pb_width * 0.5), 0.02], false);
    }
    // check for quit (typically the Esc key)
    if (psychoJS.experiment.experimentEnded || psychoJS.eventManager.getKeys({keyList:['escape']}).length > 0) {
      return quitPsychoJS('The [Escape] key was pressed. Goodbye!', false);
    }

    // check if the Routine should terminate
    if (!continueRoutine) {  // a component has requested a forced-end of Routine
      return Scheduler.Event.NEXT;
    }

    continueRoutine = false;  // reverts to True if at least one component still running
    for (const thisComponent of resource_checker_pbComponents)
      if ('status' in thisComponent && thisComponent.status !== PsychoJS.Status.FINISHED) {
        continueRoutine = true;
        break;
      }

    // refresh the screen if continuing
    if (continueRoutine) {
      return Scheduler.Event.FLIP_REPEAT;
    } else {
      return Scheduler.Event.NEXT;
    }
  };
}


