    // *resource_download_complete_keys* updates
    if (((psychoJS.serverManager.getResourceStatus(resource_names).description == 'DOWNLOADED')) && resource_download_complete_keys.status === PsychoJS.Status.NOT_STARTED) {
      // keep track of start time/frame for later
      resource_download_complete_keys.tStart = t;  // (not accounting for frame time here)
      resource_download_complete_keys.frameNStart = frameN;  // exact frame index

      // keyboard checking is just starting
      psychoJS.window.callOnFlip(function() { resource_download_complete_keys.clock.reset(); });  // t=0 on next screen flip
      psychoJS.window.callOnFlip(function() { resource_download_complete_keys.start(); }); // start on screen flip
      psychoJS.window.callOnFlip(function() { resource_download_complete_keys.clearEvents(); });
    }

    if (resource_download_complete_keys.status === PsychoJS.Status.STARTED) {
      let theseKeys = resource_download_complete_keys.getKeys({keyList: ['y', 'n', 'left', 'right', 'space'], waitRelease: false});
      _resource_download_complete_keys_allKeys = _resource_download_complete_keys_allKeys.concat(theseKeys);
      if (_resource_download_complete_keys_allKeys.length > 0) {
        resource_download_complete_keys.keys = _resource_download_complete_keys_allKeys[_resource_download_complete_keys_allKeys.length - 1].name;  // just the last key pressed
        resource_download_complete_keys.rt = _resource_download_complete_keys_allKeys[_resource_download_complete_keys_allKeys.length - 1].rt;
        // a response ends the routine
        continueRoutine = false;
      }
    }

    // check for quit (typically the Esc key)
    if (psychoJS.experiment.experimentEnded || psychoJS.eventManager.getKeys({keyList:['escape']}).length > 0) {
      return quitPsychoJS('The [Escape] key was pressed. Goodbye!', false);
    }

    // check if the Routine should terminate
    if (!continueRoutine) {  // a component has requested a forced-end of Routine
      return Scheduler.Event.NEXT;
    }

    continueRoutine = false;  // reverts to True if at least one component still running
    for (const thisComponent of resource_download_completeComponents)
      if ('status' in thisComponent && thisComponent.status !== PsychoJS.Status.FINISHED) {
        continueRoutine = true;
        break;
      }

    // refresh the screen if continuing
    if (continueRoutine) {
      return Scheduler.Event.FLIP_REPEAT;
    } else {
      return Scheduler.Event.NEXT;
    }
  };
}


function resource_download_completeRoutineEnd(snapshot) {
  return async function () {
    //--- Ending Routine 'resource_download_complete' ---
    for (const thisComponent of resource_download_completeComponents) {
      if (typeof thisComponent.setAutoDraw === 'function') {
        thisComponent.setAutoDraw(false);
      }
    }
    resource_download_complete_keys.stop();
    // the Routine "resource_download_complete" was not non-slip safe, so reset the non-slip timer
    routineTimer.reset();

    // Routines running outside a loop should always advance the datafile row
    if (currentLoop === psychoJS.experiment) {
      psychoJS.experiment.nextEntry(snapshot);
    }
    return Scheduler.Event.NEXT;
  }
}


var show_imagesComponents;
function show_imagesRoutineBegin(snapshot) {
  return async function () {
    TrialHandler.fromSnapshot(snapshot); // ensure that .thisN vals are up to date

    //--- Prepare to start Routine 'show_images' ---
    t = 0;
    show_imagesClock.reset(); // clock
    frameN = -1;
    continueRoutine = true; // until we're told otherwise
    routineTimer.add(1.000000);
    // update component parameters for each repeat
    show_image.setImage(image);
    // keep track of which components have finished
    show_imagesComponents = [];
    show_imagesComponents.push(show_image);

    for (const thisComponent of show_imagesComponents)
      if ('status' in thisComponent)
        thisComponent.status = PsychoJS.Status.NOT_STARTED;
    return Scheduler.Event.NEXT;
  }
}


var frameRemains;
function show_imagesRoutineEachFrame() {
  return async function () {
    //--- Loop for each frame of Routine 'show_images' ---
    // get current time
    t = show_imagesClock.getTime();
    frameN = frameN + 1;// number of completed frames (so 0 is the first frame)
    // update/draw components on each frame

    // *show_image* updates
    if (t >= 0.0 && show_image.status === PsychoJS.Status.NOT_STARTED) {
      // keep track of start time/frame for later
      show_image.tStart = t;  // (not accounting for frame time here)
      show_image.frameNStart = frameN;  // exact frame index

      show_image.setAutoDraw(true);
    }

    frameRemains = 0.0 + 1.0 - psychoJS.window.monitorFramePeriod * 0.75;  // most of one frame period left
    if (show_image.status === PsychoJS.Status.STARTED && t >= frameRemains) {
      show_image.setAutoDraw(false);
    }
    // check for quit (typically the Esc key)
    if (psychoJS.experiment.experimentEnded || psychoJS.eventManager.getKeys({keyList:['escape']}).length > 0) {
      return quitPsychoJS('The [Escape] key was pressed. Goodbye!', false);
    }

    // check if the Routine should terminate
    if (!continueRoutine) {  // a component has requested a forced-end of Routine
      return Scheduler.Event.NEXT;
    }

    continueRoutine = false;  // reverts to True if at least one component still running
    for (const thisComponent of show_imagesComponents)
      if ('status' in thisComponent && thisComponent.status !== PsychoJS.Status.FINISHED) {
        continueRoutine = true;
        break;
      }

    // refresh the screen if continuing
    if (continueRoutine && routineTimer.getTime() > 0) {
      return Scheduler.Event.FLIP_REPEAT;
    } else {
      return Scheduler.Event.NEXT;
    }
  };
}


function show_imagesRoutineEnd(snapshot) {
  return async function () {
    //--- Ending Routine 'show_images' ---
    for (const thisComponent of show_imagesComponents) {
      if (typeof thisComponent.setAutoDraw === 'function') {
        thisComponent.setAutoDraw(false);
      }
    }
    // Routines running outside a loop should always advance the datafile row
    if (currentLoop === psychoJS.experiment) {
      psychoJS.experiment.nextEntry(snapshot);
    }
    return Scheduler.Event.NEXT;
  }
}


var never_ending_routineComponents;
function never_ending_routineRoutineBegin(snapshot) {
  return async function () {
    TrialHandler.fromSnapshot(snapshot); // ensure that .thisN vals are up to date

    //--- Prepare to start Routine 'never_ending_routine' ---
    t = 0;
    never_ending_routineClock.reset(); // clock
    frameN = -1;
    continueRoutine = true; // until we're told otherwise
    // update component parameters for each repeat
    // keep track of which components have finished
    never_ending_routineComponents = [];
    never_ending_routineComponents.push(never_ending_text);

    for (const thisComponent of never_ending_routineComponents)
      if ('status' in thisComponent)
        thisComponent.status = PsychoJS.Status.NOT_STARTED;
    return Scheduler.Event.NEXT;
  }
}

import { v4 as uuidv4 } from 'uuid';
import { test, expect } from '@playwright/test';
import constants from '../../../../constants';

import { PropertyElement, Navigator, Graph, LoginPage, SymbolPanel, ContextMenu, Header } from '../../../../DSL/allClasses';

test('K.1.6.1.18. Переход по ссылкам вокруг связи', async ({ page }) => {
    /*
    https://confluence.silaunion.ru/pages/viewpage.action?pageId=2428871107
    */

    const dataBaseName: string = 'K.1.6.1.18_' + uuidv4();
    const modelName: string = uuidv4();
    const edgeName: string = ' [Edges with attributes]';
    const firstLocaleModelName: object = { enName: "Test 1", ruName: "Тест 1" };
    const secondLocaleModelName: object = { enName: "Test 2", ruName: "Тест 2" };
    const elementProperty = new PropertyElement(page);
    const navigator = new Navigator(page);
    const graph = new Graph(page);
    const loginPage = new LoginPage(page);
    const symbolPanel = new SymbolPanel(page);
    const contextMenu = new ContextMenu(page);
    const header = new Header(page);
    const attributesToAdd: = ['test_attribute', 'select123456789', 'date', 'node', 'datatime', 'text', 'mselect123456789', 'number', 'period', 'json', 'link', 'string', 'times', 'boolean'];
    const attributesLocaleValue:object = {
        link: { ruName: "ruLink", enName: 'enLink', ruLink: "www.ya.ru", enLink: "www.google.com" },
        text: { ruName: 'ruText', enName: 'enText' },
        string: { ruName: 'ruString', enName: 'enString' },
        selection: { ruName: 'РУ11', enName: 'EN11' },
        mselection: { ruName: ['РУ21', 'РУ22', 'РУ23'], enName: ['EN21', 'EN22', 'EN23'] },
    };
    await page.goto('/');
    // Условие:
    await loginPage.signIn({});
    // Создать БД
    await contextMenu.createBD(dataBaseName);
    // Создать модель
    await contextMenu.createModel(modelName, dataBaseName);
    // Перенести 2 объекта на холст и провести связь между ними
    await navigator.openSymbolPanel();
    const positionFirstObject = { x: 210, y: 200 };
    const positionSecondObject = { x: 710, y: 220 };
    const positionEdge = {
        x: positionFirstObject.x + 190, y: positionFirstObject.y + 40
    };
    await symbolPanel.dragSymbolToGraph(constants.TEST_METHODOLOGY_SYMBOL_OWAS, positionFirstObject.x, positionFirstObject.y);
    await symbolPanel.dragSymbolToGraph(constants.TEST_METHODOLOGY_SYMBOL_TO, positionSecondObject.x, positionSecondObject.y);
    await graph.createEdgeBetweenElements(positionFirstObject.x, positionFirstObject.y, positionSecondObject.x, positionSecondObject.y);
    // Отрыть дерево созданной БД
    await navigator.clickOnItemMenu(dataBaseName);
    // Создать модель с именем "Тест 1" для русской локализации и "Test 1" для английской локализации
    await contextMenu.createModel(firstLocaleModelName.ruName, dataBaseName);
    await navigator.clickOnItemMenu(firstLocaleModelName.ruName, { button: 'right' });
    await contextMenu.clickProperties();
    await elementProperty.editAttributeStr('', 'Имя модели', firstLocaleModelName);
    await elementProperty.clickSaveButton();
    // Создать модель с именем "Тест 2" для русской локализации и "Test 2" для английской локализации
    await contextMenu.createModel(secondLocaleModelName.ruName, dataBaseName);
    await navigator.clickOnItemMenu(secondLocaleModelName.ruName, { button: 'right' });
    await contextMenu.clickProperties();
    await elementProperty.editAttributeStr('', 'Имя модели', secondLocaleModelName);
    await elementProperty.clickSaveButton();

    await test.step('1.Создание определения связи', async () => {
        // Возвращаемся на вкладку со связью
        await graph.openTab(modelName);
        await graph.createEdgeDefinition(positionEdge.x, positionEdge.y);
    });

    await test.step('2.Добавление атрибутов определению связи и ввод значений для двух локализаций', async () => {
        // Активируем чекбокс "Объекты", чтобы они были видны в дереве
        await navigator.enableObjectsDisplay();
        // Открыть дерево объекта, тем самым увидим связь в навигаторе
        await navigator.clickOnItemMenu(constants.TEST_METHODOLOGY_SYMBOL_OWAS, { button: 'left' }, 10);
        // Открываю модальное окно свойств связи
        await navigator.clickOnItemMenu(edgeName, { clickCount: 2 }, 10);
        await elementProperty.addAttributes(attributesToAdd);
        // Задаем значение каждому атрибуту
        // json
        await elementProperty.editAttributeJson();
        // datatime
        await elementProperty.editAttributeDatatime();
        // date
        await elementProperty.editAttributeData();
        // link (two locale)
        await elementProperty.editAttributeLink('', 'link', attributesLocaleValue.link);
        // node
        await elementProperty.editAttributeNode(firstLocaleModelName.ruName);
        // text (two locale)
        await elementProperty.editAttributeStr('', 'text', attributesLocaleValue.text);
        // time 
        await elementProperty.editAttributeTime();
        // string (two locale)
        await elementProperty.editAttributeStr('', 'string', attributesLocaleValue.string);
        // number
        await elementProperty.editAttributeNumber('1098374', 'number');
        // test_attribute
        await elementProperty.editAttributeNumber('1837410', 'test_attribute');
        // period
        await elementProperty.editAttributePeriod('22.02.2022', '23.02.2022');
        // selection
        await elementProperty.editAttributeSelection(attributesLocaleValue.selection.ruName);
        // mselection
        await elementProperty.editAttributeMultipleSelection(attributesLocaleValue.mselection.ruName);
        // Клик "Сохранить"
        await elementProperty.clickSaveButton();
    });

    await test.step('3.Смена локализации на английскую. Проверка смены значений', async () => {
        // Выйти из приложения 
        await header.logOut();
        await loginPage.signIn({ locale: "EN" });
        // Активируем чекбокс "Объекты", чтобы они были видны в дереве
        await navigator.enableObjectsDisplay();
        // Раскрываем дерево БД
        await navigator.clickOnItemMenu(dataBaseName, { button: 'left' }, 15);
        await page.waitForTimeout(constants.SHORT_WAIT);
        // Раскрываем дерево объекта
        await navigator.clickOnItemMenu(constants.TEST_METHODOLOGY_SYMBOL_OWAS, { button: 'left' }, 15);
        // Клик ПКМ по определению связи в дереве Навигатора → Свойства
        await navigator.clickOnItemMenu(edgeName, { button: 'right' }, 15);
        await contextMenu.clickProperties();
        // Проверка, что в окне "Свойства" отображаются добавленные атрибуты со значениями для английской локализации (link, string, text, node, select, mselect)
        // assert link
        await expect(elementProperty.getValueAttribute('link')).toContainText(attributesLocaleValue.link.enName);
        // assert string
        await expect(elementProperty.getValueAttribute('string')).toContainText(attributesLocaleValue.string.enName);
        // assert text
        await expect(elementProperty.getValueAttribute('text')).toContainText(attributesLocaleValue.text.enName);
        // assert node 
        await expect(elementProperty.getValueAttribute('node')).toHaveText(firstLocaleModelName.enName);
        // assert select 
        await expect(elementProperty.getValueAttribute(/^select123456789/)).toHaveText(attributesLocaleValue.selection.enName);
        // assert mselect
        await expect(elementProperty.getValueAttribute(/^mselect123456789/)).toHaveText(attributesLocaleValue.mselection.enName.join(""));
    });

    await test.step('4.Изменение значений у атрибутов для одной локализации', async () => {
        // Задаем новые значения для английской локали
        // link 
        await elementProperty.editAttributeLink('1');
        // string
        await elementProperty.editAttributeStr('2', 'string');
        // text
        await elementProperty.editAttributeStr('3', 'text');
        // Клик по кнопке Сохранить в окне Свойства
        await elementProperty.clickSaveButton();
        // Клик ПКМ по определению связи в дереве Навигатора → Свойства
        await navigator.clickOnItemMenu(edgeName, { button: 'right' }, 15);
        await contextMenu.clickProperties();
        // Проверка, что в окне "Свойства" отображаются изменённые атрибуты со значениями для английской локализации (link, string, text)
        // assert link
        await expect(elementProperty.getValueAttribute('link')).toContainText(attributesLocaleValue.link.enName + '1');
        // assert string
        await expect(elementProperty.getValueAttribute('string')).toContainText(attributesLocaleValue.string.enName + '2');
        // assert text
        // text.fixme('https://jira.silaunion.ru/browse/BPM-7068') Курсор должен стоять в конце строки при редактировании атрибута "text" - сейчас в начале
        // await expect(elementProperty.getValueAttribute('text')).toContainText(attributesLocaleValue.text.enName + '3');
        await elementProperty.clickSaveButton();
    });

    await test.step('5.Смена локализации на русскую. Проверка смены значений', async () => {
        // Выйти из приложения 
        await header.logOut();
        await loginPage.signIn({});
        // Активируем чекбокс "Объекты", чтобы они были видны в дереве
        await navigator.enableObjectsDisplay();
        // Раскрываем дерево БД
        await navigator.clickOnItemMenu(dataBaseName, { button: 'left' }, 15);
        await page.waitForTimeout(constants.SHORT_WAIT);
        // Раскрываем дерево объекта
        await navigator.clickOnItemMenu(constants.TEST_METHODOLOGY_SYMBOL_OWAS, { button: 'left' }, 15);
        // Клик ПКМ по определению связи в дереве Навигатора → Свойства
        await navigator.clickOnItemMenu(edgeName, { button: 'right' }, 15);
        await contextMenu.clickProperties();
        // Проверка, что в окне “Свойства“ отображаются атрибуты со значениями для русской локализации без изменений
        // assert link
        await expect(elementProperty.getValueAttribute('link')).toContainText(attributesLocaleValue.link.ruName);
        // assert string
        await expect(elementProperty.getValueAttribute('string')).toContainText(attributesLocaleValue.string.ruName);
        // assert text
        await expect(elementProperty.getValueAttribute('text')).toContainText(attributesLocaleValue.text.ruName);
        // assert node 
        await expect(elementProperty.getValueAttribute('node')).toHaveText(firstLocaleModelName.ruName);
        // assert select 
        await expect(elementProperty.getValueAttribute(/^select123456789/)).toHaveText(attributesLocaleValue.selection.ruName);
        // assert mselect
        await expect(elementProperty.getValueAttribute(/^mselect123456789/)).toHaveText(attributesLocaleValue.mselection.ruName.join(""));
    });

    await test.step('6.Изменение значений у атрибутов', async () => {
        /*
        Поменять значения всех атрибутов
Клик по кнопке Сохранить в окне Свойства
Клик ПКМ по определению связи в дереве Навигатора → Свойства
Ожидаемый результат: в окне Свойства отображаются изменённые атрибуты со значениями для русской локализации.  
У атрибутов Выбор/Множественный выбор значение изменилось. 
У атрибута “Ссылка на документ“ значение изменилось
        */


    });

    await test.step('7.Удаление значений у атрибутов', async () => {

    });

}, constants.TEST_TIMEOUT);

