    const ComponentBase* componentBase = componentMap[i];
    const std::size_t componentDataSize = componentBase->GetSize();

    std::size_t currentSize = toArch->entityIds.size() * componentDataSize;

    componentBase->MoveData(&fromArch->componentData[j][entityIndex * componentDataSize],
        &toArch->componentData[i][currentSize]);
    componentBase->DestroyData(&fromArch->componentData[j][entityIndex * componentDataSize]);
}

void ECS::SwapComponentData(const size_t compTypeIndex, Archetype* arch, size_t index, size_t entityIndex) {
    const ComponentBase* componentBase = componentMap[compTypeIndex];
    const std::size_t componentSize = componentBase->GetSize();

    const auto lastEntity = arch->entityIds.size() - 1;

    componentBase->MoveData(&arch->componentData[index][lastEntity * componentSize],
        &arch->componentData[index][entityIndex * componentSize]);
    componentBase->DestroyData(&arch->componentData[index][lastEntity * componentSize]);
}

void ECS::RemoveAndAllocateComponentData(const size_t compTypeIndex, Archetype* fromArchetype, Archetype* toArchetype, size_t i, size_t j, size_t entityIndex) {
    const ComponentBase* const componentBase = componentMap[compTypeIndex];
    const std::size_t componentDataSize = componentBase->GetSize();

    size_t currentSize = toArchetype->entityIds.size() * componentDataSize;
    const size_t lastEntity = fromArchetype->entityIds.size() - 1;

    componentBase->MoveData(&fromArchetype->componentData[j][entityIndex * componentDataSize],
        &toArchetype->componentData[i][currentSize]);

    if (entityIndex != lastEntity) {
        componentBase->MoveData(&fromArchetype->componentData[j][lastEntity * componentDataSize],
            &fromArchetype->componentData[j][entityIndex * componentDataSize]);
    }

    componentBase->DestroyData(&fromArchetype->componentData[j][lastEntity * componentDataSize]);
}

