                if ((k & i) == 0 && (ixj > k) && (dir == (mat[offset + k] > mat[offset + ixj])))
                {
                    // Swap elements
                    temp = mat[offset + k];
                    mat[offset + k] = mat[offset + ixj];
                    mat[offset + ixj] = temp;
                }
            }
            __syncthreads();
        }
    }
}

bool isSorted(int* data, int size) {
  for (int i = 0; i < size - 1; i++) {
    if (data[i] > data[i + 1])
      return false;
  }
  return true;
}

