#define ROWS 1024
#define COLS 1024
#define ITERATIONS 10

global void bitonicSortKernel(int mat, int iteration, bool dir)
{
int idx = blockIdx.x * blockDim.x + threadIdx.x;
int offset = idx * COLS;
int i, j, k;
int temp;

for (i = 1 << (iteration - 1); i > 0; i = i >> 1)
{
for (j = i; j > 0; j = j >> 1)
{
for (k = 0; k < (COLS >> 1); ++k)
{
int ixj = k ^ j;
if ((k & i) == 0 && (ixj > k) && (dir == (mat[offset + k] > mat[offset + ixj])))
{
// Swap elements
temp = mat[offset + k];
mat[offset + k] = mat[offset + ixj];
mat[offset + ixj] = temp;
}
}
__syncthreads();
}
}
}

